# Writes the hedra command files (and palette-exact textures) of the sorting room: room.txt (floor,
# back wall, wainscot, window, pigeonholes, clock), belt.txt (the conveyor: rubber, rails, legs, drums,
# the hanging intake hopper), cleat.txt, parcel_red/green/cream.txt, confetti.txt, hand.txt (the
# clock's minute hand), props.txt (mail sacks, a stamp desk). Run from models/env:
# /usr/bin/python3 make_env.py
# Positions are written in the SCENE's frame (glTF: Y up, +Z towards the camera) and converted to
# hedra's (Z up, front -Y): hedra (x, y, z) = (X, -Z, Y). Colours are exact Paper 8 (sRGB 0..1).
import os
from PIL import Image

HEX = {"navy": "1f244b", "plum": "654053", "brick": "a8605d", "tan": "d1a67e", "cream": "f6e79c",
       "pale": "b6cf8e", "green": "60ae7b", "teal": "3c6b64"}
RGB = {k: tuple(int(v[i:i + 2], 16) for i in (0, 2, 4)) for k, v in HEX.items()}
C = {k: " ".join(f"{c / 255:.4f}" for c in v) for k, v in RGB.items()}


def mat(name, col, emit=False):
    s = f"material new {name} --base-color {C[col]} --no-slot"
    return s + (f" --emission {C[col]}" if emit else "")


def box(name, x0, x1, y0, y1, z0, z1, material, drop=None):
    """an axis-aligned box given in the SCENE frame (X right, Y up, Z towards the camera)"""
    cx, cy, cz = (x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2
    L = [f"add mesh cube --name {name} --size 1 --location {cx:.3f} {-cz:.3f} {cy:.3f}",
         f"scale {x1 - x0:.3f} {z1 - z0:.3f} {y1 - y0:.3f}", "apply --scale", f"material assign {material}"]
    if drop:   # delete faces nobody sees: a hedra `select face where` test on normals
        L += [f"active {name}", "mode edit", f'select face where "{drop}"', "delete only-faces", "mode object"]
    return L


os.makedirs("textures", exist_ok=True)

# ---------------------------------------------------------------- textures (drawn, palette-exact)
# floor planks: 16 x 7.6 m at 0.2 m a texel -> 80 x 38; planks 3 texels wide along X, brick seams,
# staggered end joints
im = Image.new("RGB", (80, 38), RGB["tan"])
for row in range(0, 38, 4):
    for x in range(80):
        im.putpixel((x, row), RGB["brick"])
    off = (row * 7) % 13
    for x in range(off, 80, 13 + (row % 3)):
        for y in range(row, min(row + 4, 38)):
            im.putpixel((x, y), RGB["brick"])
im.save("textures/floor.png")
# wallpaper: 16 x 3.7 m at 0.2 m -> 80 x 18; pale green with green stripes, a cream dot between them
im = Image.new("RGB", (80, 18), RGB["pale"])
for x in range(0, 80, 5):
    for y in range(18):
        im.putpixel((x, y), RGB["green"])
for x in range(2, 80, 5):
    for y in range(2 + (x // 5) % 2 * 3, 18, 6):
        im.putpixel((x, y), RGB["cream"])
        im.putpixel((x + 1, y), RGB["cream"])
im.save("textures/wallpaper.png")
# wainscot: 16 x 1.3 m at 0.2 m -> 80 x 7; teal boards, navy seams every 6 (the plum chutes stand
# out against it)
im = Image.new("RGB", (80, 7), RGB["teal"])
for x in range(0, 80, 6):
    for y in range(7):
        im.putpixel((x, y), RGB["navy"])
im.save("textures/wainscot.png")

# ---------------------------------------------------------------- room
r = ["# The sorting room: plank floor (16 x 7.6 m), the back wall at z -3.4 (wallpaper over a teal",
     "# wainscot and a tan dado rail), a window on the left, pigeonholes on the right, a round clock",
     "# above the middle chute (its minute hand is the game bone `hand`). Generated by make_env.py.",
     "new", "material new Floor --base-color 1 1 1 --no-slot", "material new Paper --base-color 1 1 1 --no-slot",
     "material new Panel --base-color 1 1 1 --no-slot", mat("Rail", "tan"),
     mat("Frame", "tan"), mat("Pane", "teal"), mat("Bar", "pale"), mat("Back", "plum"),
     mat("Letter", "cream"), mat("Rim", "brick"), mat("Face", "cream"), mat("Tick", "navy")]
# floor: top face only, UV from the top
r += box("Floor", -8, 8, -0.1, 0, -3.4, 4.2, "Floor", "normal.z < 0.9")
r += ["active Floor", "mode edit", "select all", "uv project-from-view top --scale-to-bounds", "mode object",
      "material texture Floor base-color textures/floor.png"]
# wallpaper (y 1.3..5) and wainscot (0..1.3, 0.05 proud), front faces only
r += box("Paper", -8, 8, 1.3, 5.0, -3.5, -3.4, "Paper", "normal.y > -0.9")
r += ["active Paper", "mode edit", "select all", "uv project-from-view front --scale-to-bounds", "mode object",
      "material texture Paper base-color textures/wallpaper.png"]
r += box("Panel", -8, 8, 0, 1.3, -3.5, -3.35, "Panel", "normal.y > -0.9")
r += ["active Panel", "mode edit", 'select face where "normal.y < -0.9"', "uv project-from-view front --scale-to-bounds",
      "mode object", "material texture Panel base-color textures/wainscot.png"]
r += box("Dado", -8, 8, 1.25, 1.42, -3.4, -3.28, "Rail", "normal.z < -0.5 || normal.y > 0.9")
# window (left): a tan frame round four teal panes, pale cross bars
wx0, wx1, wy0, wy1 = -6.3, -4.5, 2.5, 4.0
r += box("WinTop", wx0 - 0.12, wx1 + 0.12, wy1, wy1 + 0.14, -3.4, -3.28, "Frame", "normal.y > 0.9")
r += box("WinBot", wx0 - 0.2, wx1 + 0.2, wy0 - 0.16, wy0, -3.4, -3.2, "Frame", "normal.y > 0.9")
r += box("WinL", wx0 - 0.12, wx0, wy0, wy1, -3.4, -3.28, "Frame", "normal.y > 0.9")
r += box("WinR", wx1, wx1 + 0.12, wy0, wy1, -3.4, -3.28, "Frame", "normal.y > 0.9")
r += box("Pane", wx0, wx1, wy0, wy1, -3.4, -3.38, "Pane", "normal.y > -0.9")
r += box("BarV", (wx0 + wx1) / 2 - 0.06, (wx0 + wx1) / 2 + 0.06, wy0, wy1, -3.38, -3.3, "Bar", "normal.y > 0.9")
r += box("BarH", wx0, wx1, (wy0 + wy1) / 2 - 0.06, (wy0 + wy1) / 2 + 0.06, -3.38, -3.3, "Bar", "normal.y > 0.9")
# pigeonholes (right): a tan box 2.1 x 1.5, 0.35 deep, 4 x 3 cells with plum backs and a few letters
px0, px1, py0, py1 = 4.15, 6.35, 2.35, 3.95
r += box("PBack", px0, px1, py0, py1, -3.4, -3.37, "Back", "normal.y > -0.9")
cols, rows = 4, 3
for i in range(cols + 1):
    x = px0 + (px1 - px0) * i / cols
    r += box(f"PV{i}", x - 0.06, x + 0.06, py0, py1, -3.4, -3.05, "Frame", "normal.y > 0.9")
for j in range(rows + 1):
    y = py0 + (py1 - py0) * j / rows
    r += box(f"PH{j}", px0 - 0.06, px1 + 0.06, y - 0.06, y + 0.06, -3.4, -3.05, "Frame", "normal.y > 0.9")
for k, (i, j, h) in enumerate([(0, 0, 0.3), (1, 0, 0.22), (3, 0, 0.32), (0, 1, 0.26), (2, 1, 0.3), (1, 2, 0.24), (3, 2, 0.3)]):
    cx = px0 + (px1 - px0) * (i + 0.5) / cols
    y0 = py0 + (py1 - py0) * j / rows + 0.06
    r += box(f"L{k}", cx - 0.2, cx + 0.2, y0, y0 + h, -3.3, -3.18, "Letter", "normal.y > 0.9")
# clock: a brick rim, a cream face, twelve navy ticks at 3, 6, 9, 12 bigger; the hour hand fixed
r += [f"add mesh cylinder --name Rim --vertices 12 --radius 0.62 --depth 0.12 --location 0 3.32 3.75 --rotation 90 0 0",
      "apply --rotation", "material assign Rim",
      f"add mesh cylinder --name Face --vertices 12 --radius 0.5 --depth 0.06 --location 0 3.24 3.75 --rotation 90 0 0",
      "apply --rotation", "material assign Face"]
r += box("TickT", -0.05, 0.05, 4.07, 4.2, -3.22, -3.18, "Tick")
r += box("TickB", -0.05, 0.05, 3.3, 3.43, -3.22, -3.18, "Tick")
r += box("TickL", -0.45, -0.32, 3.70, 3.80, -3.22, -3.18, "Tick")
r += box("TickR", 0.32, 0.45, 3.70, 3.80, -3.22, -3.18, "Tick")
r += box("Hour", -0.04, 0.26, 3.70, 3.80, -3.2, -3.14, "Tick")
r += ["select all", "shade flat", "export room.glb"]
open("room.txt", "w").write("\n".join(r) + "\n")

# ---------------------------------------------------------------- belt
BX0, BX1, BZ0, BZ1, BTOP = -5.8, 5.2, -0.1, 1.1, 0.85
b = ["# The conveyor: a plum rubber belt x -5.8..5.2, z -0.1..1.1, its top at y 0.85; teal side rails",
     "# that stand 0.1 above it, four pairs of legs, a drum at each end; the intake hopper hangs over",
     "# its left end from two rods (parcels drop out of it). Generated by make_env.py.",
     "new", mat("Rubber", "plum"), mat("Metal", "teal"), mat("Drum", "pale"), mat("Tin", "teal"), mat("Trim", "tan")]
b += box("Belt", BX0, BX1, BTOP - 0.2, BTOP, BZ0, BZ1, "Rubber", "normal.z < 0.9 && normal.y > -0.9")
b += box("RailB", BX0 - 0.1, BX1 + 0.1, 0.6, BTOP + 0.1, BZ0 - 0.14, BZ0, "Metal", "normal.z < -0.9 || normal.y > 0.9")
b += box("RailF", BX0 - 0.1, BX1 + 0.1, 0.6, BTOP + 0.1, BZ1, BZ1 + 0.14, "Metal", "normal.z < -0.9")
for i, x in enumerate([-5.4, -1.9, 1.6, 4.8]):
    b += box(f"LegB{i}", x - 0.07, x + 0.07, 0, 0.6, BZ0 - 0.1, BZ0 + 0.04, "Metal", "normal.z < -0.9 || normal.y > 0.9")
    b += box(f"LegF{i}", x - 0.07, x + 0.07, 0, 0.6, BZ1 - 0.04, BZ1 + 0.1, "Metal", "normal.z < -0.9")
for n, x in (("DrumL", BX0), ("DrumR", BX1)):
    b += [f"add mesh cylinder --name {n} --vertices 8 --radius 0.16 --depth {BZ1 - BZ0 + 0.1:.2f} "
          f"--location {x:.2f} {-(BZ0 + BZ1) / 2:.2f} {BTOP - 0.14:.2f} --rotation 90 0 0", "apply --rotation",
          "material assign Drum"]
# intake hopper: a teal tin box x -5.55..-4.45, y 2.25..3.35, z -0.05..1.05, open at the bottom, a tan
# trim band, a navy mouth inside its bottom; two rods up out of the frame
hx0, hx1, hy0, hy1, hz0, hz1 = -5.55, -4.45, 2.25, 3.35, -0.05, 1.05
b += box("Hopper", hx0, hx1, hy0, hy1, hz0, hz1, "Tin", "normal.z < -0.9")
b += box("HTrim", hx0 - 0.06, hx1 + 0.06, hy0, hy0 + 0.16, hz0 - 0.06, hz1 + 0.06, "Trim", "normal.z > 0.9 || normal.z < -0.9")
for i, x in enumerate([hx0 + 0.2, hx1 - 0.2]):
    b += box(f"Rod{i}", x - 0.05, x + 0.05, hy1, 6.6, 0.45, 0.55, "Metal", "normal.y > 0.9 || normal.z < -0.9")
b += ["select all", "shade flat", "export belt.glb"]
open("belt.txt", "w").write("\n".join(b) + "\n")

# ---------------------------------------------------------------- cleat (a pool rides the belt)
open("cleat.txt", "w").write("\n".join(
    ["# A belt cleat: a brick bar across the belt (1.1 x 0.05 x 0.14), origin at its foot. The game",
     "# moves a pool of them with the belt. Generated by make_env.py.", "new", mat("Cleat", "brick")]
    + box("Cleat", -0.07, 0.07, 0.0, 0.05, -0.55, 0.55, "Cleat", "normal.z < -0.9")
    + ["shade flat", "export cleat.glb"]) + "\n")

# ---------------------------------------------------------------- parcels: one model per colour
# 0.8 x 0.5 x 0.6 m, origin at the bottom centre; a cross of twine 0.05 proud (about half a spacing:
# the straps are wide, 0.14, so they read as raised bands)
for name, wrap, twine in (("red", "brick", "cream"), ("green", "green", "cream"), ("cream", "cream", "brick")):
    p = [f"# Parcel ({name}): a box 0.8 x 0.5 x 0.6 m wrapped in {wrap}, tied with a {twine} cross of twine;",
         "# origin at its bottom centre. Generated by make_env.py.", "new", mat("Wrap", wrap), mat("Twine", twine)]
    p += box("Box", -0.4, 0.4, 0.0, 0.5, -0.3, 0.3, "Wrap")
    p += box("TwX", -0.07, 0.07, -0.05, 0.55, -0.35, 0.35, "Twine", "normal.y < -0.9")
    p += box("TwZ", -0.45, 0.45, -0.05, 0.55, -0.07, 0.07, "Twine", "normal.y < -0.9")
    p += box("Knot", -0.11, 0.11, 0.55, 0.62, -0.11, 0.11, "Twine", "normal.z < -0.9")
    p += ["select all", "shade flat", f"export parcel_{name}.glb"]
    open(f"parcel_{name}.txt", "w").write("\n".join(p) + "\n")

# ---------------------------------------------------------------- confetti (paper bits, unlit)
open("confetti.txt", "w").write("\n".join(
    ["# A paper bit: a flat cream square 0.16 m (unlit), the game throws a pool of them out of a chute",
     "# after a good sort. Generated by make_env.py.", "new", mat("Bit", "cream", True)]
    + box("Bit", -0.08, 0.08, -0.03, 0.03, -0.08, 0.08, "Bit")
    + ["set rotation 30 20 10", "shade flat", "export confetti.glb"]) + "\n")

# ---------------------------------------------------------------- the clock's minute hand
open("hand.txt", "w").write("\n".join(
    ["# The clock's minute hand: a navy bar 0.42 long pointing up from the clock's centre (0, 3.75, -3.16),",
     "# its origin at the centre (the pivot). The game ticks it round. Generated by make_env.py.",
     "new", mat("Hand", "navy")]
    + box("Hand", -0.04, 0.04, 3.72, 4.17, -3.18, -3.12, "Hand", "normal.y > 0.9")
    + ["cursor set 0 3.15 3.75", "origin set --to cursor", "set location 0 0 0", "shade flat", "export hand.glb"]) + "\n")

# ---------------------------------------------------------------- props: mail sacks, a stamp desk
s = ["# Props: three tan mail sacks with plum ties (front left), a stamp desk with an ink pad and two",
     "# stamps (front right). Generated by make_env.py.", "new", mat("Sack", "tan"), mat("Tie", "plum"),
     mat("Desk", "brick"), mat("Leg", "plum"), mat("Pad", "navy"), mat("Stamp", "tan"), mat("Knob", "plum")]
for i, (x, z, rr, sx, sz) in enumerate([(-6.0, 2.7, 0.5, 1.2, 1.0), (-5.0, 3.1, 0.45, 1.15, 0.95), (-5.6, 2.3, 0.4, 1.0, 1.1)]):
    s += [f"add mesh ico-sphere --name Sack{i} --subdivisions 1 --radius {rr} --location {x} {-z} {rr * 0.95:.2f} --rotation 0 0 {i * 37}",
          f"scale {sx} 1 {sz}", "apply --scale", "material assign Sack"]
    s += box(f"Tie{i}", x - 0.11, x + 0.11, rr * 1.75, rr * 1.75 + 0.22, z - 0.11, z + 0.11, "Tie")
s += box("Top", 3.9, 5.8, 0.82, 0.95, 2.4, 3.4, "Desk", "normal.z < -0.9")
for i, (x, z) in enumerate([(4.0, 2.5), (5.7, 2.5), (4.0, 3.3), (5.7, 3.3)]):
    s += box(f"DLeg{i}", x - 0.07, x + 0.07, 0, 0.82, z - 0.07, z + 0.07, "Leg", "normal.z < -0.9 || normal.y > 0.9")
s += box("InkPad", 4.2, 4.8, 0.95, 1.02, 2.6, 3.1, "Pad", "normal.y < -0.9")
for i, x in enumerate([5.1, 5.5]):
    s += box(f"Stamp{i}", x - 0.1, x + 0.1, 0.95, 1.15, 2.75, 2.95, "Stamp", "normal.y < -0.9")
    s += [f"add mesh ico-sphere --name Knob{i} --subdivisions 1 --radius 0.11 --location {x} -2.85 1.24",
          "material assign Knob"]
s += ["select all", "shade flat", "export props.glb"]
open("props.txt", "w").write("\n".join(s) + "\n")
print("wrote room, belt, cleat, parcel_red/green/cream, confetti, hand, props (.txt) and textures/")
